const app = document.querySelector('#app');
const state = { screen: new URLSearchParams(location.search).get('view')==='users'?'users':'booking', step: 0, date: 12, time: '', view: 'month', tab: 'Calendar', selected: 0, error: false, changes: 0, name: '', email: '', notes: '' };
const meetings = [
  { title: 'Project conversation', client: 'Sample client · new enquiry', day: 12, time: '10:00', status: 'Confirmed' },
  { title: 'Brand direction review', client: 'Sample client · branding project', day: 14, time: '14:00', status: 'Awaiting approval' },
  { title: 'Project check-in', client: 'Sample client · website project', day: 16, time: '11:30', status: 'Confirmed' }
];
const esc = value => String(value).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const components = window.WDC_COMPONENTS;
state.month = 9; state.year = 2026; state.setting = 'Availability';
state.reminders = { enabled: true, day: true, hour: true, owner: true };
const monthNames = ['January','February','March','April','May','June','July','August','September','October','November','December'];
const period = () => `${monthNames[state.month]} ${state.year}`;
let savedReminders = {...state.reminders};
const dateLabel = () => `${monthNames[state.month]} ${state.date}, ${state.year}`;
const icon = name => components.icons[name] || '';
const button = (label, action, cls = '', extra = '') => {
  const glyph = { '‹':'ChevronLeft', '›':'ChevronRight', '×':'X', '+':'Plus' }[label];
  const leading = {'Schedule a meeting':'Plus','View meeting':'CalendarClock','Copy booking link':'Link','Join meeting':'Video','Reschedule':'CalendarClock','Save changes':'Check','Add a date override':'Plus'}[label];
  const kit = glyph ? 'ad__iconButton' : cls.includes('public-') || cls==='day' || cls.startsWith('day ') ? '' : 'ad__btn';
  return `<button class="${kit} ${cls==='primary'?'ad__btn--primary':cls}" data-action="${action}" ${extra}>${glyph?icon(glyph):(leading?icon(leading):'')+label}</button>`;
};
function toast(message) { const box = document.querySelector('#announcement'); box.textContent = message; box.classList.add('visible'); clearTimeout(toast.timer); toast.timer = setTimeout(() => box.classList.remove('visible'), 3500); }
function month(booking = false) {
  const offset=(new Date(state.year,state.month,1).getDay()+6)%7;
  const length=new Date(state.year,state.month+1,0).getDate();
  return `<div class="month-toolbar">${button('‹','previous-month','','aria-label="Previous month"')}${button(period(),'pick-period','period-button','aria-label="Choose month and year" aria-haspopup="dialog"')}${button('›','next-month','','aria-label="Next month"')}</div><div class="month">${['M','T','W','T','F','S','S'].map((d,i)=>`<span class="weekday" aria-label="${['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'][i]}">${d}</span>`).join('')}${'<span></span>'.repeat(offset)}${Array.from({length},(_,i)=> { const d=i+1; const dt=new Date(state.year,state.month,d); const available = dt>=new Date(2026,9,8)&&![0,6].includes(dt.getDay()); return button(d,`date:${d}`,`day ${available?'available':''} ${state.date===d?'selected':''}`,`aria-label="${monthNames[state.month]} ${d}, ${state.year}" aria-pressed="${state.date===d}" ${booking&&!available?'disabled':''}`); }).join('')}</div>`;
}
function pickPeriod() {
 const dialog=document.createElement('dialog');dialog.className='ad period-dialog';dialog.setAttribute('aria-label','Choose month and year');
 dialog.innerHTML=`<div class="picker-head"><h2>Choose month and year</h2>${button('×','close-picker','','aria-label="Close month picker"')}</div><div class="picker-year">${button('‹','year-back','','aria-label="Previous year"')}<button id="picker-year" data-action="show-years" class="ad__btn" aria-label="Choose year">${state.year}</button>${button('›','year-next','','aria-label="Next year"')}</div><div class="month-options">${monthNames.map((m,i)=>button(m,`pick-month:${i}`,i===state.month?'selected':'',`aria-pressed="${i===state.month}"`)).join('')}</div>`;
 document.body.append(dialog);dialog.showModal();dialog.addEventListener('close',()=>dialog.remove());
}
function reminders() {
 return shell(`<header class="page-head"><div><h1>Reminders</h1><p>Help people arrive prepared, without sending the same message twice.</p></div>${button('View meetings','calendar','primary')}</header><div class="settings-layout"><nav class="settings-nav">${['Availability','Meeting types','Calendars & video','Reminders'].map(n=>button(n,`setting:${n}`,n==='Reminders'?'active':'')).join('')}</nav><div class="settings-body"><section class="panel settings-panel"><h2>Attendee reminders</h2><p>Proposed email policy. Clients can turn optional reminders off for their meeting.</p>${[['enabled','Enable optional email reminders'],['day','24 hours before'],['hour','1 hour before']].map(([k,label])=>`<div class="reminder-row"><div><strong>${label}</strong><p class="muted">${k==='enabled'?'Booking confirmations and changes remain separate.':'Skip this reminder if its scheduled time has already passed.'}</p></div><button class="reminder-switch" role="switch" aria-checked="${state.reminders[k]}" aria-label="${label}" data-action="reminder:${k}"><span></span></button></div>`).join('')}<p class="privacy-note">Times follow the meeting instant; email copy shows the recipient’s time zone.</p></section><section class="panel settings-panel"><h2>Your notifications</h2><div class="reminder-row"><div><strong>Notify me about new requests and changes</strong><p class="muted">A personal setting. Staff choose their own preferences.</p></div><button class="reminder-switch" role="switch" aria-checked="${state.reminders.owner}" aria-label="Notify me about requests and changes" data-action="reminder:owner"><span></span></button></div></section><section class="panel settings-panel"><h2>Delivery and recovery</h2><div class="reminder-row"><div><strong>Cal.com email reminders</strong><p class="muted">Configuration and delivery visibility must be verified on your account before launch.</p></div><span class="pill request">Setup required</span></div><p>Show “Managed by Cal.com” when the provider supplies no delivery receipt. Never call a configured reminder delivered.</p><div class="reminder-row"><div><strong>SMS and WhatsApp</strong><p class="muted">Off until pricing, channel support and consent are verified.</p></div><span class="pill cancelled">Off</span></div><p>Rescheduling replaces reminders for the old time. Cancellation, decline and opt-out suppress pending optional reminders.</p>${button('Preview failed delivery','reminder-failure')}</section><div class="save-bar"><p>${state.changes?`${state.changes} unsaved changes`:'No unsaved changes'} · Preview only</p><div class="button-row">${button('Discard','discard')}${button('Save changes','save','primary',state.changes?'':'disabled')}</div></div></div></div>`,true);
}
function booking() {
  const steps = ['Meeting','Date & time','Your details','Review'];
  let content = '';
  if(state.step===0) content = `<h2>Let’s talk about your project</h2><p class="muted">A little time together to understand what you have in mind.</p><button class="choice selected" data-action="next"><span class="choices-icon" aria-hidden="true">↗</span><span class="choice-main"><b>Project conversation</b><small>30 minutes · Video call · No charge</small></span><span aria-hidden="true">→</span></button><div class="notice"><strong>Prefer to write it down?</strong>Our project enquiry form remains available.</div>${button('Tell us about your project','contact','public-secondary')}`;
  if(state.step===1) content = `<h2>Choose a date and time</h2><p class="muted">Times are shown in your selected time zone.</p><div class="timezone">${button('Africa/Lagos · UTC+1 ▾','timezone')}</div>${state.error?`<div class="notice"><strong>We couldn’t load available times.</strong>Your details are safe. Try again or send a project enquiry.${button('Try again','retry')}</div>`:`<div class="date-time"><section class="calendar-section" aria-label="Choose date">${month(true)}</section><section><h3>${dateLabel()}</h3><p class="muted">30-minute conversations</p><div class="slots">${['09:00','10:00','11:30','14:00','15:00','16:00'].map(t=>button(t,`time:${t}`,state.time===t?'selected':'',`aria-pressed="${state.time===t}"`)).join('')}</div></section></div>`}<div class="preview-state">Preview a recovery state: ${button('Availability unavailable','error')}</div>`;
  if(state.step===2) content = `<h2>A little about you</h2><p class="muted">Help us arrive prepared.</p><form id="details"><div class="fields"><label>Your name<input name="name" autocomplete="name" required value="${esc(state.name)}"></label><label>Email address<input name="email" type="email" autocomplete="email" required value="${esc(state.email)}"></label><label class="wide">What would you like to discuss?<textarea name="notes">${esc(state.notes)}</textarea></label></div><p class="privacy-note">In the finished flow, we’ll use these details to manage your meeting. This preview sends nothing.</p></form>`;
  if(state.step===3) content = `<h2>Everything look right?</h2><p class="muted">Check the details before confirming.</p><dl class="review-list"><dt>Meeting</dt><dd>Project conversation</dd><dt>When</dt><dd>${dateLabel()} · ${state.time}</dd><dt>Time zone</dt><dd>Africa/Lagos · UTC+1</dd><dt>Duration</dt><dd>30 minutes</dd><dt>Location</dt><dd>Video call · link after confirmation</dd><dt>Your details</dt><dd>${esc(state.name)}<br>${esc(state.email)}</dd></dl>`;
  if(state.step===4) content = `<div class="success-mark" aria-hidden="true">✓</div><h2>You’re all set</h2><p>This is the proposed confirmation screen. No meeting was booked.</p><dl class="review-list"><dt>Conversation</dt><dd>${dateLabel()} · ${state.time}<br>Africa/Lagos · 30 minutes</dd><dt>Next steps</dt><dd>Your confirmation would include the video link and secure options to reschedule or cancel.</dd></dl><div class="button-row">${button('Manage meeting','manage','public-primary')}${button('Back to booking','restart','public-secondary')}</div>`;
  return `<header class="hero"><div class="hero-nav"><span class="wordmark">We Dig Creativity</span><span>Meet the studio</span></div><span class="eyebrow">A conversation is a good place to start</span><h1>Make time for your next idea.</h1><p>Choose a time that works for you. We’ll bring the questions, the attention and a fresh perspective.</p></header><main class="booking-wrap"><aside class="panel summary"><span class="pill">We Dig Creativity</span><h2>Project conversation</h2><p>Tell us where you are and where you want to go.</p><div class="figure">30 <small>min</small></div><div class="summary-row">Video conversation</div><div class="summary-details"><div class="summary-row">No charge for this first conversation</div><p class="muted">A clear next step, whether we work together now or later.</p></div></aside><section class="panel booking-body"><ol class="step-indicator">${steps.map((s,i)=>`<li class="${state.step===i?'current':''}" ${state.step===i?'aria-current="step"':''}>${i+1}. ${s}</li>`).join('')}</ol>${content}${state.step<4?`<div class="actions">${button(state.step?'Back':'Contact instead',state.step?'back':'contact','public-secondary')}${button(state.step===3?'Confirm sample booking':'Continue','next','public-primary',state.step===1&&!state.time?'disabled':'')}</div>`:''}</section></main>`;
}
function shell(content, settings = false) {
  return components.shell.replace('__PAGE__',components.demo + content);
}
function agenda(items) { return items.length?`<div class="agenda-list">${items.map(m=>`<button class="agenda-row" data-action="meeting:${meetings.indexOf(m)}"><span class="agenda-time">${m.time}<small>Oct ${m.day}</small></span><span class="agenda-copy"><b>${m.title}</b><small>${m.client}</small><span class="pill ${m.status==='Awaiting approval'?'request':m.status==='Cancelled'?'cancelled':''}">${m.status}</span></span><span aria-hidden="true">→</span></button>`).join('')}</div>`:`<div class="meeting-empty"><strong>Nothing here yet</strong><p>Meetings will appear here when their status changes.</p>${button('View calendar','calendar')}</div>`; }
function workspace() {
  const m = meetings[state.selected];
  const visibleMeetings = state.year===2026 && state.month===9 ? meetings : [];
  let calendar = agenda(visibleMeetings);
  if(state.tab==='Requests') calendar=agenda(meetings.filter(m=>m.status==='Awaiting approval'));
  else if(state.tab==='History') calendar=agenda(meetings.filter(m=>m.status==='Cancelled'));
  else if(state.view==='month') calendar=`<div class="calendar-table">${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map(d=>`<span class="weekday">${d}</span>`).join('')}${Array.from({length:Math.ceil(((new Date(state.year,state.month,1).getDay()+6)%7+new Date(state.year,state.month+1,0).getDate())/7)*7},(_,i)=>{const d=i-(new Date(state.year,state.month,1).getDay()+6)%7+1;return `<div class="calendar-cell ${d===5?'today':''}">${d>0&&d<=new Date(state.year,state.month+1,0).getDate()?`<span class="date-number">${d}</span>${visibleMeetings.filter(m=>m.day===d&&m.status!=='Cancelled').map(m=>`<button class="event ${m.status==='Awaiting approval'?'request':''}" data-action="meeting:${meetings.indexOf(m)}"><span>${m.time}</span><span>${m.title}</span></button>`).join('')}`:''}</div>`;}).join('')}</div><div class="mobile-calendar">${month()}<h3 class="upcoming-title">Upcoming meetings</h3>${agenda(visibleMeetings)}</div>`;
  else if(state.view==='week' && !visibleMeetings.length) calendar=agenda([]);
  else if(state.view==='week') calendar=`<div class="week-grid" role="region" aria-label="Week calendar. Scroll horizontally to view all days" tabindex="0" data-lenis-prevent><div class="week-row head"><div>Time</div>${[12,13,14,15,16].map(d=>`<div>Oct ${d}</div>`).join('')}</div>${['09:00','10:00','11:30','14:00'].map(t=>`<div class="week-row"><div class="time">${t}</div>${[12,13,14,15,16].map(d=>`<div>${meetings.filter(m=>m.day===d&&m.time===t).map(m=>`<button class="event" data-action="meeting:${meetings.indexOf(m)}">${m.title}</button>`).join('')}</div>`).join('')}</div>`).join('')}</div>`;
  else if(state.view==='day') calendar=agenda(visibleMeetings.filter(m=>m.day===state.date));
  return shell(`<header class="page-head"><div><h1>Meetings</h1><p>A little preparation. Better conversations.</p></div>${button('Schedule a meeting','booking','primary')}</header><section class="panel next-meeting"><div><span class="eyebrow">Next conversation · sample</span><h3>Project conversation</h3><span class="muted">Oct 12 · 30 minutes · Video call</span></div><span class="next-time">10:00</span><div class="button-row">${button('View meeting','meeting:0','primary')}${button('Copy booking link','copy')}</div></section><div class="tabs">${['Calendar','Requests','History'].map(t=>button(t,`tab:${t}`,state.tab===t?'active':'')).join('')}</div><div class="meeting-layout"><section class="panel calendar-panel"><div class="toolbar"><div class="toolbar-nav">${button('‹','previous-month','','aria-label="Previous period"')}${button(period(),'pick-period','period-button','aria-label="Choose month and year" aria-haspopup="dialog"')}${button('›','next-month','','aria-label="Next period"')}</div><div class="view-buttons">${['agenda','day','week','month'].map(v=>button(v[0].toUpperCase()+v.slice(1),`view:${v}`,state.view===v?'active':'',`data-view="${v}"`)).join('')}</div></div><h2 class="day-agenda-title">${state.tab==='Calendar'?'Your schedule':state.tab}</h2>${calendar}</section><aside class="panel detail" id="meeting-detail">${button('×','close-detail','close-detail','aria-label="Close meeting details"')}<span class="pill ${m.status==='Awaiting approval'?'request':''}">${m.status}</span><h2>${m.title}</h2><p class="muted">${m.client}</p><dl><dt>Date & time</dt><dd>October ${m.day}, 2026 · ${m.time}</dd><dt>Duration</dt><dd>30 minutes</dd><dt>Location</dt><dd>Video call</dd><dt>Project context</dt><dd>Discuss goals, scope and the best next step.</dd></dl><div class="detail-actions">${m.status==='Awaiting approval'?button('Approve sample request','approve','primary'):button('Join meeting','join','primary')}${button('Reschedule','reschedule')}${button('Cancel meeting','cancel')}</div><div class="timeline"><strong>Activity</strong><p>Sample booking received.<br>Confirmation state shown for design review.</p></div></aside></div>`);
}
function availability() { return shell(`<header class="page-head"><div><h1>Availability</h1><p>Your time, on your terms.</p></div>${button('View booking page','booking','primary')}</header><div class="settings-layout"><nav class="settings-nav">${['Availability','Meeting types','Calendars & video','Reminders'].map(n=>button(n,`setting:${n}`,n==='Availability'?'active':'')).join('')}</nav><div class="settings-body"><section class="panel settings-panel"><h2>Weekly hours</h2><p>Set your usual week. Date overrides take priority.</p><div class="timezone">${button('Africa/Lagos · UTC+1 ▾','timezone')}</div>${['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'].map((d,i)=>`<div class="hours-row"><strong>${d}</strong><div class="hours-control">${i<5?`${button('09:00',`hours:${d}`)}<span>to</span>${button('17:00',`hours:${d}`)}`:'Unavailable'}</div>${button('+',`period:${d}`,'plus',`aria-label="Add hours for ${d}"`)}</div>`).join('')}</section><section class="panel settings-panel"><h2>Date overrides</h2><p>Take a day off or add hours for a particular date.</p><div class="override"><div><strong>October 23, 2026</strong><p class="muted">Unavailable · Sample override</p></div>${button('Edit','override')}</div><p>${button('Add a date override','override')}</p></section><section class="panel settings-panel"><h2>Booking boundaries</h2><p>Proposed defaults; yours to adjust.</p><div class="button-row">${button('24 hours notice','boundary')}${button('15 minute buffers','boundary')}${button('30 day booking window','boundary')}</div></section><div class="save-bar"><p>${state.changes?`${state.changes} unsaved change${state.changes===1?'':'s'}`:'No unsaved changes'} · Preview only</p><div class="button-row">${button('Discard','discard')}${button('Save changes','save','primary',state.changes?'':'disabled')}</div></div></div></div>`,true); }
function render() {
 app.innerHTML=state.screen==='users'?users():state.screen==='booking'?booking():state.screen==='meetings'?workspace():state.setting==='Reminders'?reminders():availability();
 document.querySelectorAll('[data-screen]').forEach(b=>b.setAttribute('aria-current',b.dataset.screen===state.screen));
 app.querySelectorAll('.page-head').forEach(el=>el.classList.add('ad__head'));
 app.querySelectorAll('.pill').forEach(el=>{el.classList.add('ad__pill'); if(el.classList.contains('request'))el.classList.add('ad__pill--warn'); else if(el.classList.contains('cancelled'))el.classList.add('ad__pill--flat'); else if(el.textContent==='Confirmed')el.classList.add('ad__pill--good');});
 app.querySelectorAll('.settings-panel,.calendar-panel,.detail').forEach(el=>{
  const title=el.querySelector('h2');const titleText=title?.textContent || 'Meeting details';title?.remove();
  const replacement=document.createElement('div');replacement.innerHTML=components.panel.replace('__TITLE__',esc(titleText)).replace('__CONTENT__','<div class="meeting-panel-body">'+el.innerHTML+'</div>');
  const panel=replacement.firstElementChild;panel.classList.add(...[...el.classList].filter(c=>c!=='panel'));if(el.id)panel.id=el.id;el.replaceWith(panel);
 });
 app.querySelectorAll('.choices-icon').forEach(el=>el.innerHTML=icon('Video'));
 app.querySelectorAll('.choice>span:last-child,.agenda-row>span:last-child').forEach(el=>el.innerHTML=icon('ArrowRight'));
 app.querySelectorAll('.success-mark').forEach(el=>el.innerHTML=icon('Check'));
 app.querySelectorAll('.hero-nav .wordmark').forEach(el=>el.innerHTML=components.logo+'<span>We Dig Creativity</span>');
 const menu=app.querySelector('.ad__topMenu');if(menu)menu.dataset.action='drawer';
 const theme=app.querySelector('.ad__themeBtn');if(theme){theme.dataset.action='theme';theme.innerHTML=icon(document.documentElement.classList.contains('dark')?'Sun':'Moon');}
 const pin=app.querySelector('[data-tour="sidebar-pin"]');if(pin)pin.dataset.action='collapse';
 app.querySelectorAll('a[href^="/admin"]').forEach(el=>{el.dataset.action=el.getAttribute('href')==='/admin/settings'?'settings':'preview-link';el.setAttribute('href','#');});
 if(state.screen==='users'){app.querySelector('.ad__topTitle').textContent='Users';app.querySelector('[data-action="calendar"]')?.classList.remove('is-on');app.querySelector('.ad__nav [data-action="settings"]')?.classList.add('is-on');app.querySelector('.ad__demo span')?.replaceChildren(document.createTextNode('Sample users for design review. No invitations or account changes are sent.'));}
 if(state.screen==='availability'){app.querySelector('[data-action="calendar"]')?.classList.remove('is-on');app.querySelector('.ad__nav [data-action="settings"]')?.classList.add('is-on');}
}
document.addEventListener('click',e=>{
 const target=e.target.closest('[data-screen],[data-action]');if(!target)return;e.preventDefault();
 if(target.dataset.screen){state.screen=target.dataset.screen;render();return;}
 const [action,value]=target.dataset.action.split(':');
 if(action.startsWith('user-')){handleUsers(action,value,target);return;}
 if(action==='pick-period'){pickPeriod();return;}
 if(action==='close-picker'){target.closest('dialog').close();return;}
 if(action==='pick-year'){target.closest('dialog').querySelector('#picker-year').textContent=value;target.closest('dialog').querySelector('.year-options')?.remove();return;}
 if(action==='show-years'){const dialog=target.closest('dialog');if(!dialog.querySelector('.year-options')){const center=Number(dialog.querySelector('#picker-year').textContent);dialog.insertAdjacentHTML('beforeend',`<div class="year-options" aria-label="Choose year">${Array.from({length:12},(_,i)=>button(center-5+i,`pick-year:${center-5+i}`)).join('')}</div>`);}return;}
 if(action==='year-back'||action==='year-next'){const el=target.closest('dialog').querySelector('#picker-year');el.textContent=Number(el.textContent)+(action==='year-back'?-1:1);return;}
 if(action==='pick-month'){state.month=Number(value);state.year=Number(target.closest('dialog').querySelector('#picker-year').textContent);state.date=1;state.time='';target.closest('dialog').close();render();return;}
 if(action==='previous-month'||action==='next-month'){const dt=new Date(state.year,state.month+(action==='previous-month'?-1:1),1);state.year=dt.getFullYear();state.month=dt.getMonth();state.date=1;state.time='';render();return;}
 if(action==='reminder'){state.reminders[value]=!state.reminders[value];state.changes++;toast('Reminder preference changed · save to keep the sample policy');render();return;}
 if(action==='reminder-failure'){toast('Sample failure: connection unavailable. Reconcile delivery before retrying; uncertain delivery is not blindly resent.');return;}
 if(action==='next'){if(state.step===2){const form=document.querySelector('#details');if(!form.reportValidity())return;const data=new FormData(form);state.name=data.get('name');state.email=data.get('email');state.notes=data.get('notes');}state.step=Math.min(4,state.step+1);}
 else if(action==='back')state.step=Math.max(0,state.step-1);
 else if(action==='date'){state.date=Number(value);state.time='';}
 else if(action==='time')state.time=value+':'+target.dataset.action.split(':')[2];
 else if(action==='view')state.view=value;
 else if(action==='tab')state.tab=value;
 else if(action==='calendar'){state.screen='meetings';state.tab='Calendar';state.view='month';}
 else if(action==='meeting'){state.selected=Number(value);render();document.querySelector('#meeting-detail').classList.add('open');return;}
 else if(action==='close-detail'){document.querySelector('#meeting-detail').classList.remove('open');return;}
 else if(action==='cancel'){document.querySelector('#confirm').showModal();return;}
 else if(action==='approve'){meetings[state.selected].status='Confirmed';toast('Updated · sample request approved');}
 else if(action==='booking'||action==='reschedule'||action==='restart'){state.screen='booking';state.step=action==='reschedule'?1:0;state.time='';}
 else if(action==='settings')state.screen='availability';
 else if(action==='error')state.error=true;
 else if(action==='retry')state.error=false;
 else if(['period','hours','override','boundary'].includes(action)){state.changes++;toast('Sample change added. Save or discard below.');}
 else if(action==='save'){savedReminders={...state.reminders};state.changes=0;toast('Saved · preview only');}
 else if(action==='discard'){state.reminders={...savedReminders};state.changes=0;toast('Sample changes discarded');}
 else if(action==='manage'){state.screen='meetings';state.selected=0;}
 else if(action==='drawer'){const dialog=document.createElement('dialog');dialog.className='drawer ad';dialog.innerHTML=`${app.querySelector('.ad__sideInner').innerHTML}<div>${button('Close menu','close-menu')}</div>`;document.body.append(dialog);dialog.showModal();return;}
 else if(action==='collapse'){app.querySelector('.ad__wrap').classList.toggle('is-collapsed');return;}
 else if(action==='theme'){document.querySelector('#theme').click();render();return;}
 else if(action==='close-menu'){target.closest('dialog').remove();return;}
 else if(action==='timezone')toast('Preview time zone: Africa/Lagos (UTC+1). A searchable zone picker is included in the implementation plan.');
 else if(action==='copy')toast('The finished flow will copy your public booking link. This preview has no live booking URL.');
 else if(action==='join')toast('The confirmed provider video link will open here. No sample meeting room exists.');
 else if(action==='contact')toast('The existing project enquiry form stays available alongside booking.');
 else if(action==='setting'){if(value==='Availability'||value==='Reminders'){state.screen='availability';state.setting=value;}else toast(`${value} is included in the integration plan.`);}
 else toast('This design preview shows October 2026 and the Meetings workspace.');
 render();
});
document.querySelector('#theme').addEventListener('click',()=>{const dark=document.documentElement.classList.toggle('dark');document.querySelector('#theme').textContent=dark?'Light theme':'Dark theme';document.querySelector('#theme').setAttribute('aria-label',dark?'Switch to light theme':'Switch to dark theme');});
document.querySelector('#keep').onclick=()=>document.querySelector('#confirm').close();
document.querySelector('#cancel-confirm').onclick=()=>{meetings[state.selected].status='Cancelled';document.querySelector('#confirm').close();render();toast('Updated · sample meeting cancelled');};

const sampleUsers=[
 {id:0,name:'Studio owner',email:'owner@example.com',role:'Owner',status:'Active',last:'5 Oct 2026',initials:'SO'},
 {id:1,name:'Morgan James',email:'morgan@example.com',role:'Staff',status:'Active',last:'4 Oct 2026',initials:'MJ'},
 {id:2,name:'Ada Cole',email:'ada@example.com',role:'Staff',status:'Deactivated',last:'27 Sep 2026',initials:'AC'},
 {id:3,name:'Bisi Taylor',email:'bisi@example.com',role:'Client',status:'Active',last:'3 Oct 2026',initials:'BT'}
];
const sampleInvites=[{name:'Alex Reed',email:'alex@example.com',role:'Staff',status:'Pending',delivery:'Queued',expires:'12 Oct 2026'},{name:'Sam Blake',email:'sam@example.com',role:'Staff',status:'Expired',delivery:'Failed',expires:'2 Oct 2026'}];
state.userTab='Team';state.userQuery='';state.userRole='All roles';state.userStatus='All statuses';state.userPage=1;state.userSize=10;state.userSelected=[];
function users(){
 const list=sampleUsers.filter(u=>state.userTab==='Clients'?u.role==='Client':u.role!=='Client').filter(u=>(u.name+' '+u.email).toLowerCase().includes(state.userQuery.toLowerCase())&&(state.userRole==='All roles'||u.role===state.userRole)&&(state.userStatus==='All statuses'||u.status===state.userStatus));
 const inviteList=sampleInvites.map((u,id)=>({...u,originalIndex:id})).filter(u=>(u.name+' '+u.email).toLowerCase().includes(state.userQuery.toLowerCase())&&(state.userRole==='All roles'||u.role===state.userRole)&&(state.userStatus==='All statuses'||u.status===state.userStatus));
 const total=state.userTab==='Invitations'?inviteList.length:list.length;const pages=Math.max(1,Math.ceil(total/state.userSize));state.userPage=Math.min(state.userPage,pages);const start=(state.userPage-1)*state.userSize;
 const person=u=>`<div class="user-person"><span class="user-avatar">${esc(u.initials||u.name.split(' ').map(n=>n[0]).slice(0,2).join(''))}</span><span><b>${esc(u.name)}</b><small>${esc(u.email)}</small></span></div>`;
 const rows=state.userTab==='Invitations'?inviteList.slice(start,start+state.userSize).map((u,j)=>`<tr><td><div class="user-person-cell">${u.id===0?'<span class="user-check-spacer"></span>':`<input type="checkbox" class="user-select" data-action="user-select:${u.id===undefined?'invite-'+u.originalIndex:u.id}" aria-label="Select ${esc(u.name)}" ${state.userSelected.includes(String(u.id===undefined?'invite-'+u.originalIndex:u.id))?'checked':''}>`}${person(u)}</div></td><td>${u.role}</td><td><span class="ad__pill ${u.status==='Pending'?'ad__pill--warn':'ad__pill--flat'}">${u.status}</span></td><td>${u.expires}</td><td><span class="ad__pill ${u.delivery==='Failed'?'ad__pill--bad':'ad__pill--flat'}">${u.delivery}</span></td><td>${button('Manage',`user-invitation:${u.originalIndex}`,'','aria-label="Manage invitation for '+esc(u.name)+'"')}</td></tr>`).join(''):list.slice(start,start+state.userSize).map(u=>`<tr><td><div class="user-person-cell">${u.id===0?'<span class="user-check-spacer"></span>':`<input type="checkbox" class="user-select" data-action="user-select:${u.id===undefined?'invite-'+u.originalIndex:u.id}" aria-label="Select ${esc(u.name)}" ${state.userSelected.includes(String(u.id===undefined?'invite-'+u.originalIndex:u.id))?'checked':''}>`}${person(u)}</div></td><td><span class="ad__pill ${u.role==='Owner'?'ad__pill--brand':'ad__pill--flat'}">${u.role}</span></td><td><span class="ad__pill ${u.status==='Active'?'ad__pill--good':'ad__pill--bad'}">${u.status}</span></td><td>${u.last}</td><td>${u.id===0?'<span class="ad__pill ad__pill--flat">You</span>':button('View account',`user-detail:${u.id}`)}</td></tr>`).join('');
 return shell(`<header class="page-head"><div><span class="eyebrow">Settings</span><h1>Users</h1><p>The right people. The right access.</p></div>${button('Invite user','user-invite','primary')}</header><nav class="tabs" aria-label="User lists">${['Team','Invitations','Clients'].map(t=>button(t,`user-tab:${t}`,state.userTab===t?'active':'',`aria-pressed="${state.userTab===t}"`)).join('')}</nav><section class="panel user-panel"><h2>${state.userTab==='Team'?'Studio team':state.userTab==='Invitations'?'Invitations':'Client accounts'}</h2><p>${state.userTab==='Team'?'Manage who can open the studio workspace.':state.userTab==='Invitations'?'See whether an invitation is still valid and what happened to its email.':'Account access stays separate from the client’s project record.'}</p>${`<div class="user-toolbar"><label class="user-search"><span class="ad__sr">Search users</span>${icon('Search')}<input type="search" id="user-search" placeholder="Search by name or email" value="${esc(state.userQuery)}"></label><div class="button-row">${button(state.userRole,'user-role')}${button(state.userStatus,'user-status')}${button('Export','user-export')}</div></div>`}${state.userSelected.length?`<div class="user-bulk"><b>${state.userSelected.length} selected</b>${button(state.userTab==='Invitations'?'Cancel invitations':'Deactivate accounts','user-bulk')}${button('Clear selection','user-clear-selection')}</div>`:''}<div class="ad__scroll user-table-region" tabindex="0" aria-label="${state.userTab} table. Scroll horizontally to see all columns"><table class="ad__t user-table"><thead><tr><th><label class="user-select-all"><input type="checkbox" class="user-select" data-action="user-select-all" aria-label="Select eligible rows on this page">Person</label></th><th>Role</th><th>Status</th>${state.userTab==='Invitations'?'<th>Works until</th><th>Email</th>':'<th>Last sign-in</th>'}<th>Actions</th></tr></thead><tbody>${rows||'<tr><td colspan="5"><p>No records match these filters. Clear the search or choose another status.</p>'+button('Clear filters','user-clear')+'</td></tr>'}</tbody></table></div><div class="user-table-foot"><span>${total?start+1:0}–${Math.min(start+state.userSize,total)} of ${total} sample records</span><div class="user-pagination">${button(state.userSize+' per page','user-size-picker')}<nav aria-label="Users pagination">${button('‹','user-prev','','aria-label="Previous page" '+(state.userPage===1?'disabled':''))}<span>Page ${state.userPage} of ${pages}</span>${button('›','user-next','','aria-label="Next page" '+(state.userPage===pages?'disabled':''))}</nav></div></div></section><details class="user-permissions"><summary>What each role can do</summary><div class="ad__scroll"><table class="ad__t user-table"><thead><tr><th>Area</th><th>Owner</th><th>Staff</th><th>Client</th></tr></thead><tbody><tr><td>Clients, projects, forms and content</td><td>Manage</td><td>Manage</td><td>Own portal only</td></tr><tr><td>Money, settings and user access</td><td>Manage</td><td>No access</td><td>Own invoices only</td></tr></tbody></table></div></details>`,true);
}
function userDialog(title,body){document.querySelectorAll('.users-dialog').forEach(d=>d.remove());const d=document.createElement('dialog');d.className='ad addlg users-dialog';d.setAttribute('aria-label',title);d.innerHTML=`<div class="addlg__in"><div class="addlg__h"><h2>${esc(title)}</h2>${button('×','user-close','addlg__x','aria-label="Close user dialog"')}</div><div class="addlg__b">${body}</div></div>`;document.body.append(d);d.showModal();d.addEventListener('close',()=>d.remove());}
function userDetail(i){const u=sampleUsers[i];userDialog(u.name,`<div class="user-account-head"><span class="user-avatar">${u.initials}</span><div><b>${u.name}</b><p>${u.email}</p></div><span class="ad__pill ${u.status==='Active'?'ad__pill--good':'ad__pill--bad'}">${u.status}</span></div><p>${u.role==='Client'?'Client portal access.':'Studio workspace access.'} <b>${u.role}</b></p><div class="user-detail-grid"><section><h3>Account</h3><dl><dt>Email</dt><dd>${u.email}</dd><dt>Last sign-in</dt><dd>${u.last} · sample</dd><dt>Sign-in</dt><dd>Password · sample configuration</dd></dl></section><section><h3>Access</h3><p>${u.role==='Owner'?'All studio areas.':u.role==='Staff'?'Clients, projects, forms and content. Money and account administration stay with owners.':'Their own projects, invoices and support conversations.'}</p></section></div><div class="user-action-list">${button('Edit name',`user-edit:${i}`)}${button('Send password reset',`user-reset:${i}`)}${button('Sign out all sessions',`user-sessions:${i}`)}${u.role==='Client'?button('View as client',`user-support:${i}`):button(u.role==='Staff'?'Change role':'Review role',`user-change-role:${i}`)}${button(u.status==='Active'?'Deactivate account':'Reactivate account',`user-access:${i}`)}</div><section class="user-activity"><h3>Activity</h3><p>Sample account access shown for design review. Production history will show actual changes and delivery outcomes.</p></section>`);}
function handleUsers(action,value,target){
 const i=Number(value),u=sampleUsers[i];
 if(action==='user-tab'){state.userTab=value;state.userQuery='';state.userRole='All roles';state.userStatus='All statuses';state.userPage=1;state.userSelected=[];render();}
 else if(action==='user-select'){const k=String(value);state.userSelected=state.userSelected.includes(k)?state.userSelected.filter(x=>x!==k):[...state.userSelected,k];render();}
 else if(action==='user-select-all'){state.userSelected=state.userSelected.length?[]:Array.from(document.querySelectorAll('.user-table tbody .user-select')).map(el=>el.dataset.action.split(':')[1]);render();}
 else if(action==='user-clear-selection'){state.userSelected=[];render();}
 else if(action==='user-prev'||action==='user-next'){state.userPage+=action==='user-next'?1:-1;state.userSelected=[];render();}
 else if(action==='user-size-picker'){userDialog('Items per page',`<div class="user-action-list">${[10,25,50,100].map(n=>button(n+' per page','user-size:'+n)).join('')}</div>`);}
 else if(action==='user-size'){state.userSize=Number(value);state.userPage=1;state.userSelected=[];target.closest('dialog').close();render();}
 else if(action==='user-export'){userDialog('Export users',`<p>${state.userSelected.length?state.userSelected.length+' selected rows':'Current filtered list'}. Credentials and session tokens are excluded.</p><div class="user-action-list">${button('CSV — spreadsheet','user-format:CSV')}${button('JSON — structured data','user-format:JSON')}</div><p class="user-hint">Sample preview only. Production exports require owner permissions and an audit event.</p>`);}
 else if(action==='user-format'){target.closest('dialog').close();toast(value+' export selected · sample preview only');}
 else if(action==='user-bulk'){userDialog('Review bulk action',`<p>${state.userSelected.length} selected. ${state.userTab==='Invitations'?'Invitation links will stop working.':'Access ends and sessions are revoked. Your own account and the last active owner are protected.'}</p><p>Each successful or failed result will be shown separately.</p><div class="button-row">${button('Cancel','user-close')}${button('Confirm sample bulk action','user-bulk-apply','primary')}</div>`);}
 else if(action==='user-bulk-apply'){for(const k of state.userSelected){if(k.startsWith('invite-'))sampleInvites[Number(k.slice(7))].status='Cancelled';else if(Number(k)!==0)sampleUsers[Number(k)].status='Deactivated';}state.userSelected=[];target.closest('dialog').close();render();toast('Updated · sample selection only');}
 else if(action==='user-close')target.closest('dialog').close();
 else if(action==='user-clear'){state.userQuery='';state.userRole='All roles';state.userStatus='All statuses';state.userPage=1;state.userSelected=[];render();}
 else if(action==='user-role'||action==='user-status'){const role=action==='user-role';userDialog(role?'Filter by role':'Filter by status',`<div class="user-action-list">${(role?['All roles','Owner','Staff','Client']:(state.userTab==='Invitations'?['All statuses','Pending','Expired','Cancelled']:['All statuses','Active','Deactivated'])).map(n=>button(n,`${role?'user-pick-role':'user-pick-status'}:${n}`)).join('')}</div>`);}
 else if(action==='user-pick-role'||action==='user-pick-status'){state[action==='user-pick-role'?'userRole':'userStatus']=value;state.userPage=1;state.userSelected=[];target.closest('dialog').close();render();}
 else if(action==='user-detail')userDetail(i);
 else if(action==='user-invite'){userDialog('Invite user',`<p>Send a secure invitation. They choose their own password.</p><form id="user-invite-form"><label>Name<input name="name" required autocomplete="off"></label><label>Email<input name="email" required type="email" autocomplete="off"></label><fieldset><legend>Studio access</legend><label class="user-radio"><input type="radio" name="role" value="Staff" checked> Staff</label><p>Clients, projects, forms and content. No money, settings or account administration.</p><label class="user-radio"><input type="radio" name="role" value="Owner"> Owner</label><p>Full studio access, including money and managing users.</p></fieldset><p class="user-hint">One-time link, valid for seven days. Resending replaces the earlier link.</p><div class="button-row">${button('Cancel','user-close')}${button('Queue sample invitation','user-send','primary')}</div></form>`);}
 else if(action==='user-send'){const f=document.querySelector('#user-invite-form');if(!f.reportValidity())return;const v=new FormData(f);sampleInvites.unshift({name:String(v.get('name')),email:String(v.get('email')),role:String(v.get('role')),status:'Pending',delivery:'Queued',expires:'12 Oct 2026'});target.closest('dialog').close();state.userTab='Invitations';render();toast('Sample invitation queued. No email was sent.');}
 else if(action==='user-invitation'){const inv=sampleInvites[i];userDialog(`Invitation for ${inv.name}`,`<p>${esc(inv.email)}</p><dl><dt>Role</dt><dd>${inv.role}</dd><dt>Link</dt><dd>${inv.status} · ${inv.expires}</dd><dt>Email</dt><dd>${inv.delivery} · sample</dd></dl><p>Sending again creates a new link and cancels the old one.</p><div class="button-row">${button('Send again',`user-resend:${i}`,'primary')}${button('Cancel invitation',`user-cancel-invite:${i}`)}</div>`);}
 else if(action==='user-resend'||action==='user-cancel-invite'){sampleInvites[i].status=action==='user-resend'?'Pending':'Cancelled';if(action==='user-resend')sampleInvites[i].delivery='Queued';target.closest('dialog').close();render();toast(action==='user-resend'?'Sample invitation queued again. The previous link is replaced.':'Sample invitation cancelled. No messages were sent.');}
 else if(action==='user-edit'){userDialog(`Edit ${u.name}`,`<form id="user-edit-form"><label>Name<input name="name" required value="${esc(u.name)}"></label><p class="user-hint">Email is their verified identity. Changing it needs a separate verified-address flow.</p>${button('Save name',`user-save-name:${i}`,'primary')}</form>`);}
 else if(action==='user-save-name'){const f=document.querySelector('#user-edit-form');if(!f.reportValidity())return;u.name=f.elements.name.value;target.closest('dialog').close();render();toast('Updated · sample name');}
 else if(action==='user-support'){userDialog('View as client',`<p>You’ll see ${u.name}’s portal for up to 15 minutes. This is read-only: no payments, messages or account changes.</p><label>Support reason<textarea required id="support-reason" placeholder="What are you helping them with?"></textarea></label><p class="user-hint">The real owner and the client remain separate in the audit.</p>${button('Open sample support view',`user-support-open:${i}`,'primary')}`);}
 else if(action==='user-support-open'){const reason=document.querySelector('#support-reason');if(!reason.reportValidity())return;userDialog('Read-only support view',`<div class="user-support-banner"><b>Viewing as ${u.name}</b><span>Read-only · sample · 15 minutes</span>${button('Exit support view','user-close')}</div><h3>The client’s portal</h3><p>Production will show this client’s real projects and invoices. This design preview does not expose an account or grant access.</p>`);}
 else if(action==='user-reset'||action==='user-sessions'||action==='user-access'||action==='user-change-role'){const titles={'user-reset':'Send password reset','user-sessions':'Sign out all sessions','user-access':u.status==='Active'?'Deactivate account':'Reactivate account','user-change-role':'Change role'};const notes={'user-reset':'The recovery link goes to their verified email. You cannot see or choose their password.','user-sessions':'They’ll be signed out on every device. They can sign back in if their access is active.','user-access':u.status==='Active'?'Access ends and their sessions are revoked. Their authored work stays in history.':'They can sign in again.','user-change-role':'Owner grants full access to money, settings and managing people. The last active owner can never be removed.'};userDialog(titles[action],`<p><b>${u.name}</b> · ${u.email}</p><p>${notes[action]}</p><div class="button-row">${button('Cancel','user-close')}${button('Confirm sample action',`user-confirm:${i}`,'primary',`data-kind="${action}"`)}</div>`);}
 else if(action==='user-confirm'){const kind=target.dataset.kind;if(kind==='user-access')u.status=u.status==='Active'?'Deactivated':'Active';if(kind==='user-change-role')u.role=u.role==='Staff'?'Owner':'Staff';target.closest('dialog').close();render();toast(kind==='user-reset'?'Sample recovery email queued. Nothing was sent.':'Updated · sample account state');}
}
document.addEventListener('input',e=>{if(e.target.id==='user-search'){const start=e.target.selectionStart;state.userQuery=e.target.value;state.userPage=1;state.userSelected=[];render();const input=document.querySelector('#user-search');input.focus();try{input.setSelectionRange(start,start);}catch{}}});

render();
